import assert from "node:assert/strict";
import { test } from "node:test";
import type { RoofLineMeasurement } from "./roofLineMeasurements.ts";
import {
  roofLineAdjustedFeet,
  roofLineCountableFeet,
  roofLineIsComplete,
  roofLineMeasurementTotals,
  roofLinePitchFactor,
  roofLineRequiresPitch,
} from "./roofLineMeasurements.ts";

function line(
  overrides: Partial<RoofLineMeasurement> & Pick<RoofLineMeasurement, "type" | "feet">,
): RoofLineMeasurement {
  return {
    id: "line",
    start: { x: 0, y: 0 },
    end: { x: 1, y: 1 },
    ...overrides,
  };
}

test("rake pitch is required; hip and valley pitch are optional", () => {
  assert.equal(roofLineRequiresPitch("rake"), true);
  assert.equal(roofLineRequiresPitch("hip"), false);
  assert.equal(roofLineRequiresPitch("valley"), false);
  assert.equal(roofLineRequiresPitch("eave"), false);
});

test("an unpitched rake is incomplete and stays out of totals", () => {
  const rake = line({ type: "rake", feet: 12 });
  assert.equal(roofLineIsComplete(rake), false);
  assert.equal(roofLineAdjustedFeet(rake), 12);
  assert.equal(roofLineCountableFeet(rake), 0);
  assert.equal(roofLineMeasurementTotals([rake]).rake, 0);
});

test("a pitched rake counts slope-adjusted feet", () => {
  const rake = line({ type: "rake", feet: 12, pitchRiseOver12: 6 });
  const expected = 12 * roofLinePitchFactor(6);
  assert.equal(roofLineIsComplete(rake), true);
  assert.equal(roofLineCountableFeet(rake), expected);
  assert.equal(roofLineMeasurementTotals([rake]).rake, expected);
});

test("unpitched hip and valley still count plan feet", () => {
  const hip = line({ type: "hip", feet: 10 });
  const valley = line({ type: "valley", feet: 8 });
  assert.equal(roofLineIsComplete(hip), true);
  assert.equal(roofLineIsComplete(valley), true);
  assert.equal(roofLineCountableFeet(hip), 10);
  assert.equal(roofLineCountableFeet(valley), 8);
  const totals = roofLineMeasurementTotals([hip, valley]);
  assert.equal(totals.hip, 10);
  assert.equal(totals.valley, 8);
});

